import std/strutils
import atcoder/extra/numeric/float256

func parseHexWord(
    text: string,
): uint64 =
  for character in text:
    let digit =
      case character
      of '0' .. '9':
        uint64(ord(character) - ord('0'))
      of 'a' .. 'f':
        uint64(ord(character) - ord('a') + 10)
      of 'A' .. 'F':
        uint64(ord(character) - ord('A') + 10)
      else:
        raiseAssert "invalid hexadecimal digit"

    result =
      (result shl 4) or
      digit

