"""

let vectorFields =
  divisionVectors.splitWhitespace()

doAssert vectorFields.len == 4672 * 12

for vectorIndex in 0 ..< 4672:
  let
    offset =
      vectorIndex * 12

    lhs =
      fromBits(
        parseHexWord(vectorFields[offset]),
        parseHexWord(vectorFields[offset + 1]),
        parseHexWord(vectorFields[offset + 2]),
        parseHexWord(vectorFields[offset + 3]),
      )

    rhs =
      fromBits(
        parseHexWord(vectorFields[offset + 4]),
        parseHexWord(vectorFields[offset + 5]),
        parseHexWord(vectorFields[offset + 6]),
        parseHexWord(vectorFields[offset + 7]),
      )

    actual =
      toBits(lhs / rhs)

  doAssert actual.word3 ==
    parseHexWord(vectorFields[offset + 8])
  doAssert actual.word2 ==
    parseHexWord(vectorFields[offset + 9])
  doAssert actual.word1 ==
    parseHexWord(vectorFields[offset + 10])
  doAssert actual.word0 ==
    parseHexWord(vectorFields[offset + 11])

echo "FLOAT256_DIVISION_CONTRACT_OK"
